# Деплой 17.10.2026 (2): подписание З-2 (workflow, b24people, z2) + /b24/set-branch. Портал ЭДО D:\anescom_edo
$ErrorActionPreference = "Stop"
$root = "D:\anescom_edo"; $app = "$root\app"; $py = "$root\.venv\Scripts\python.exe"
$bak = "$root\backup_20261017_z2_" + (Get-Date -Format HHmmss)
New-Item -ItemType Directory -Force "$bak\templates","$bak\static","$bak\data" | Out-Null
Copy-Item "$app\*.py" $bak; Copy-Item "$app\templates\*" "$bak\templates"; Copy-Item "$app\static\style.css" "$bak\static"
Copy-Item "$root\config.env" $bak
if (Test-Path "$root\data\edo.sqlite3") { Copy-Item "$root\data\edo.sqlite3" "$bak\data" }
Write-Host "Резервная копия: $bak"
$utf8 = New-Object System.Text.UTF8Encoding($false)
$chk = "$bak\check.py"; $state = "$bak\old_state.json"
[IO.File]::WriteAllBytes($chk, [Convert]::FromBase64String(""))
Set-Location $root; $env:EDO_ENV_FILE = "$root\config.env"
& $py $chk old $state
if ($LASTEXITCODE -ne 0) { Write-Host "Текущая версия не импортируется — деплой остановлен, ничего не менял" -ForegroundColor Red; return }
[IO.File]::WriteAllBytes("$app\workflow.py", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$app\b24people.py", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$app\z2.py", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$app\branch.py", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$app\main.py", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$app\config.py", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$app\pdfcert.py", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$app\templates\sign.html", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$app\templates\cabinet.html", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$app\templates\cabinet_doc.html", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$app\static\style.css", [Convert]::FromBase64String(""))
& $py $chk new $state
if ($LASTEXITCODE -ne 0) {
  Write-Host "ОШИБКА проверки новой версии — откат" -ForegroundColor Red
  Copy-Item "$bak\*.py" $app -Force; Copy-Item "$bak\templates\*" "$app\templates" -Force; Copy-Item "$bak\static\style.css" "$app\static" -Force
  Remove-Item "$app\workflow.py","$app\b24people.py","$app\z2.py","$app\branch.py" -ErrorAction SilentlyContinue
  Remove-Item "$app\check.py" -ErrorAction SilentlyContinue; return
}
Remove-Item "$app\check.py" -ErrorAction SilentlyContinue
$env_ = [IO.File]::ReadAllText("$root\config.env", $utf8)
if ($env_ -notmatch "(?m)^SIGN_NOTIFY_MODE=") { [IO.File]::AppendAllText("$root\config.env", "`n# --- 17.10.2026 подписание З-2 (off/test/live)`nSIGN_NOTIFY_MODE=test`n", $utf8) }
schtasks /End /TN "ANESCOM EDO" | Out-Null
Get-NetTCPConnection -LocalPort 8096 -State Listen -ErrorAction SilentlyContinue | % { Stop-Process -Id $_.OwningProcess -Force -ErrorAction SilentlyContinue }
Start-Sleep 2; schtasks /Run /TN "ANESCOM EDO" | Out-Null; Start-Sleep 8
try { Write-Host ("HEALTH: " + (Invoke-RestMethod http://127.0.0.1:8096/health | ConvertTo-Json -Compress)) -ForegroundColor Green } catch { Write-Host "HEALTH FAIL: $_" -ForegroundColor Red }
foreach ($u in @("http://127.0.0.1:8096/b24/set-branch/1?k=x","http://127.0.0.1:8096/api/z2")) { try { $r = Invoke-WebRequest $u -Method Post -UseBasicParsing; Write-Host "$u -> $($r.StatusCode)" } catch { Write-Host ("$u -> " + $_.Exception.Response.StatusCode.value__) } }
Write-Host "ГОТОВО"
